import styled from "styled-components";

export const InputImageContainer = styled.div`
    width:7rem;
    height:6rem;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px dashed #000;
    

    

    input{
        font-size: 0.75rem;
        font-weight: 400; 
        border: 0;
        width: 100%;
        height:100%;
        
        
    }
`
